public class BatchInserterTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static java.util.List<String> values(int n) {
        java.util.List<String> list = new java.util.ArrayList<>();
        for (int i = 1; i <= n; i++) {
            list.add("v" + i);
        }
        return list;
    }

    public static void main(String[] args) {
        try {
            check("three values in batches of two",
                  "[INSERT INTO logs VALUES (?),(?), INSERT INTO logs VALUES (?)]",
                  String.valueOf(BatchInserter.batches(values(3), 2)));
            check("four values in one batch",
                  "[INSERT INTO logs VALUES (?),(?),(?),(?)]",
                  String.valueOf(BatchInserter.batches(values(4), 4)));
            check("five values in batches of two",
                  "[INSERT INTO logs VALUES (?),(?), INSERT INTO logs VALUES (?),(?), INSERT INTO logs VALUES (?)]",
                  String.valueOf(BatchInserter.batches(values(5), 2)));
            check("one value",
                  "[INSERT INTO logs VALUES (?)]",
                  String.valueOf(BatchInserter.batches(values(1), 3)));
            check("batch size larger than the list",
                  "[INSERT INTO logs VALUES (?),(?)]",
                  String.valueOf(BatchInserter.batches(values(2), 10)));
            check("batch count for 7 values in batches of 3",
                  3,
                  BatchInserter.batches(values(7), 3).size());
            check("empty value list",
                  "[]",
                  String.valueOf(BatchInserter.batches(new java.util.ArrayList<String>(), 3)));
            check("batch size below 1",
                  "[]",
                  String.valueOf(BatchInserter.batches(values(3), 0)));
        } catch (RuntimeException e) {
            System.out.println("FAIL  unexpected exception -- expected a normal return but got " + e);
            failures++;
        }
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

