public class BatchInserter {

    public static final String TABLE = "logs";

    public static java.util.List<String> batches(java.util.List<String> values, int batchSize) {
        java.util.List<String> statements = new java.util.ArrayList<>();
        if (values == null || batchSize < 1) {
            return statements;
        }
        for (int start = 0; start < values.size(); start += batchSize) {
            int end = Math.min(start + batchSize, values.size());
            StringBuilder sb = new StringBuilder("INSERT INTO " + TABLE + " VALUES ");
            for (int i = start; i < end; i++) {
                if (i > start) {
                    sb.append(",");
                }
                sb.append("(?)");
            }
            statements.add(sb.toString());
        }
        return statements;
    }
}
